//#region packages/contracts/src/plugin-inventory.d.ts
type PluginSource = 'builtin' | 'store' | 'embedder';
type PluginInventoryError = Readonly<{
  code: string;
  message: string;
  reason?: string;
  hint?: string;
}>;
/** One step of a plugin's cleanup: it completed, or it threw this typed error. */
type PluginCleanupStep = Readonly<{
  status: 'ok';
}> | Readonly<{
  status: 'failed';
  error: PluginInventoryError;
}>;
/**
 * What closing the registry did for one registered plugin. A plugin without `dispose` has nothing to
 * dispose, which reads as `ok`.
 */
type PluginCleanupOutcome = Readonly<{
  provider: string;
  source: PluginSource;
  shutdown: PluginCleanupStep;
  dispose: PluginCleanupStep;
}>;
//#endregion
//#region packages/daemon/src/server/http/server-shutdown.d.ts
/** What a closed daemon runtime leaves behind, by kind of resource. */
type ShutdownReport = {
  /** Provider lease releases, by lease id. `unknown` was still in flight when the budget ran out. */
  providerReleases: {
    completed: string[];
    pending: string[];
    unknown: string[];
  };
  /** Device runners, by device id: `handedOff` was left running for the next daemon. */
  runners: {
    stopped: string[];
    handedOff: string[];
  };
  /**
   * Requests in flight at close. `abandoned` ones ignored cancellation past the drain budget and may
   * still be running, so the registration stays held while this process lives.
   */
  requests: {
    drained: number;
    abandoned: number;
  };
  sessions: {
    closed: number;
    failed: number;
  };
  platformOwners: 'closed' | 'pending';
  /** `pending` plugins were still shutting down when the budget ran out. */
  plugins: {
    disposed: string[];
    failed: {
      provider: string;
      source?: PluginCleanupOutcome['source'];
      step: 'shutdown' | 'dispose';
      error: NormalizedError;
    }[];
    pending: string[];
  };
};
//#endregion
//#region src/sdk/host-types.d.ts
type StartAgentDeviceOptions = Readonly<{
  /** Required state directory to own, resolved against the host working directory. */
  stateDir: string;
  /** The environment and working directory to run with. Defaults to one captured copy of this process's. */
  host?: HostEnvironment;
  /** Imported plugins to register after the built-ins. The plugin store is not read. */
  plugins?: readonly AgentDevicePlugin[];
}>;
type AgentDeviceHost = Readonly<{
  /** A client pinned to this instance. */
  client: AgentDeviceClient;
  /** Serializable attach config containing this instance's bearer token. Keep it inside the host. */
  clientConfig: AgentDeviceClientConfig;
  /** Reports unfinished teardown. Repeated calls share one close; never exits the process. */
  close: () => Promise<ShutdownReport>;
}>;
//#endregion
